/* @lc app=leetcode id=1357 lang=kotlin */ class Cashier(val n: Int, val discount: Int, products: IntArray, prices: IntArray, val m: Map<Int, Int> = products.indices.associate { products[it] to prices[it] }, var c: Int = 0) { fun getBill(product: IntArray, amount: IntArray): Double = product.indices.sumOf { m.getValue(product[it]) * amount[it] } * if (++c % n == 0) (100.0 - discount) / 100.0 else 1.0 }